alter table maintenance_work_orders add column if not exists due_at timestamptz;alter table maintenance_work_orders add column if not exists work_order_type text not null default 'corrective' check(work_order_type in('corrective','preventive','inspection'));alter table maintenance_work_orders add column if not exists preventive_plan_id uuid;
create table if not exists maintenance_preventive_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),asset_id uuid not null references maintenance_assets(id),code text,name text not null,description text,priority text not null default'medium'check(priority in('low','medium','high','critical')),trigger_type text not null default'calendar'check(trigger_type in('calendar','meter')),frequency_value integer,frequency_unit text check(frequency_unit in('day','week','month','year')),next_due_at timestamptz,lead_time_days integer not null default 0,estimated_minutes integer,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists maintenance_preventive_plan_tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),preventive_plan_id uuid not null references maintenance_preventive_plans(id),sequence integer not null,task text not null,instructions text,required boolean not null default true,created_at timestamptz not null default now());
create table if not exists maintenance_work_order_checklist(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),work_order_id uuid not null references maintenance_work_orders(id),sequence integer not null,task text not null,instructions text,required boolean not null default true,completed boolean not null default false,completed_at timestamptz,completed_by uuid,unique(work_order_id,sequence));
alter table maintenance_work_orders add constraint maintenance_wo_pm_fk foreign key(preventive_plan_id)references maintenance_preventive_plans(id);create unique index if not exists maintenance_one_open_pm on maintenance_work_orders(preventive_plan_id)where preventive_plan_id is not null and status not in('completed','cancelled');create index if not exists maintenance_pm_due_idx on maintenance_preventive_plans(organization_id,next_due_at)where active;
alter table maintenance_preventive_plans enable row level security;alter table maintenance_preventive_plan_tasks enable row level security;alter table maintenance_work_order_checklist enable row level security;revoke all on maintenance_preventive_plans,maintenance_preventive_plan_tasks,maintenance_work_order_checklist from anon,authenticated;grant all on maintenance_preventive_plans,maintenance_preventive_plan_tasks,maintenance_work_order_checklist to service_role;
create or replace function maintenance_generate_due_pm(p_organization_id uuid,p_actor_id uuid,p_actor_email text)returns integer language plpgsql security definer set search_path=public as $$declare p record;w uuid;n text;made integer:=0;begin for p in select*from maintenance_preventive_plans where organization_id=p_organization_id and active and trigger_type='calendar'and next_due_at<=now()+(lead_time_days||' days')::interval and not exists(select 1 from maintenance_work_orders where preventive_plan_id=maintenance_preventive_plans.id and status not in('completed','cancelled'))for update skip locked loop n='WO-'||extract(year from now()at time zone'Australia/Brisbane')::int||'-'||lpad(nextval('maintenance_work_order_seq')::text,6,'0');insert into maintenance_work_orders(organization_id,work_order_number,asset_id,work_order_type,preventive_plan_id,status,priority,title,problem_description,requested_by,requested_by_email,due_at)values(p_organization_id,n,p.asset_id,'preventive',p.id,'open',p.priority,p.name,p.description,p_actor_id,p_actor_email,p.next_due_at)returning id into w;insert into maintenance_work_order_checklist(organization_id,work_order_id,sequence,task,instructions,required)select p_organization_id,w,sequence,task,instructions,required from maintenance_preventive_plan_tasks where preventive_plan_id=p.id;insert into maintenance_work_order_history(organization_id,work_order_id,to_status,changed_by,changed_by_email)values(p_organization_id,w,'open',p_actor_id,p_actor_email);made:=made+1;end loop;return made;end$$;
revoke all on function maintenance_generate_due_pm(uuid,uuid,text)from public,anon,authenticated;grant execute on function maintenance_generate_due_pm(uuid,uuid,text)to service_role;